root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "Resources")
esc = lambda s: s.replace("\\", "\\\\").replace('"', '\\"')
keys = [k for k, *_ in T]
assert len(keys) == len(set(keys)), "duplicate key"
for i, lang in enumerate(["de", "fr", "es"]):
    lines = ["/* Generated by scripts/strings.py – edit the table there. English texts are the keys. */"]
    lines += [f'"{esc(k)}" = "{esc(row[i])}";' for k, *row in T]
    os.makedirs(os.path.join(root, f"{lang}.lproj"), exist_ok=True)
    open(os.path.join(root, f"{lang}.lproj", "Localizable.strings"), "w").write("\n".join(lines) + "\n")
print(len(T), "strings")
